package com.franco.desco.adapter.out.sqlserver.census;import com.franco.desco.adapter.out.sqlserver.shared.*;import com.franco.desco.application.census.CensusCommands.*;import com.franco.desco.application.census.port.out.CensusPersistencePort;import com.franco.desco.application.shared.*;import com.franco.desco.application.shared.pagination.PageResult;import com.franco.desco.domain.census.CensusModels;import org.springframework.jdbc.core.simple.SimpleJdbcCall;import org.springframework.stereotype.Component;import java.util.*;
@Component public class CensusSqlServerAdapter implements CensusPersistencePort{private final SqlServerPaExecutor e;private final PaPayloadFactory f;private final SimpleJdbcCall list,create,update;public CensusSqlServerAdapter(SqlServerPaFactory x,SqlServerPaExecutor e,PaPayloadFactory f){this.e=e;this.f=f;list=x.callWithResultSets("prod","PA_CensoPlantas_Sel_Historial","items");create=x.call("prod","PA_CensoPlantas_Ins_Registro");update=x.call("prod","PA_CensoPlantas_Upd_Registro");}public PersistenceResult<PageResult<CensusModels.Summary>>list(ListCensuses c,SessionIdentity i,RequestMetadata m){int p=c.page().pagina(),s=c.page().tamanio();Filter z=c.page().filtros();var filters=map("parcelaCultivoId",z==null?null:z.parcelaCultivoId(),"parcelaId",z==null?null:z.parcelaId(),"fechaDesde",z==null?null:z.fechaDesde(),"fechaHasta",z==null?null:z.fechaHasta(),"pagina",p,"tamanoPagina",s);var rs=e.executeJsonMultiResult(list,f.forQuery(i,m,Map.of("filtros",filters)));return PaAdapterSupport.page(rs.raw(),rs.rows("items"),p,s,this::summary,"No se pudo consultar el historial de censos.");}public PersistenceResult<Long>create(CreateCensus c,SessionIdentity i,RequestMetadata m){var out=e.executeJsonMutation(create,f.forWrite(i,m,c,Map.of("censo",payload(c))));return PaAdapterSupport.result(out,SqlValues.longValue(out,"nCensoPlantasId"),"No se pudo registrar el censo.");}public PersistenceResult<Void>update(UpdateCensus c,SessionIdentity i,RequestMetadata m){var out=e.executeJsonMutation(update,f.forWrite(i,m,c,Map.of("censo",payload(c))));return PaAdapterSupport.result(out,null,"No se pudo actualizar el censo.");}private Map<String,Object>payload(CreateCensus c){return map("parcelaCultivoId",c.parcelaCultivoId(),"fechaCenso",c.fechaCenso(),"plantasTotales",c.plantasTotales(),"plantasProductivas",c.plantasProductivas(),"plantasNoProductivas",c.plantasNoProductivas(),"plantasNuevas",c.plantasNuevas(),"plantasMuertas",c.plantasMuertas(),"plantasAfectadas",c.plantasAfectadas(),"observacion",c.observacion());}private Map<String,Object>payload(UpdateCensus c){var m=payload(new CreateCensus(c.parcelaCultivoId(),c.fechaCenso(),c.plantasTotales(),c.plantasProductivas(),c.plantasNoProductivas(),c.plantasNuevas(),c.plantasMuertas(),c.plantasAfectadas(),c.observacion()));m.put("censoPlantasId",c.censoPlantasId());return m;}private CensusModels.Summary summary(Map<String,Object>r){return new CensusModels.Summary(SqlValues.longValue(r,"censo_plantas_id"),SqlValues.longValue(r,"parcela_cultivo_id"),SqlValues.longValue(r,"parcela_id"),SqlValues.string(r,"parcelaCodigo"),SqlValues.string(r,"parcelaNombre"),SqlValues.string(r,"variedad"),SqlValues.localDate(r,"fecha_censo"),SqlValues.intValue(r,"plantas_totales"),SqlValues.intValue(r,"plantas_productivas"),SqlValues.intValue(r,"plantas_no_productivas"),SqlValues.intValue(r,"plantas_nuevas"),SqlValues.intValue(r,"plantas_muertas"),SqlValues.intValue(r,"plantas_afectadas"),SqlValues.string(r,"observacion"),SqlValues.bool(r,"estado"));}private static Map<String,Object>map(Object...p){Map<String,Object>m=new LinkedHashMap<>();for(int x=0;x<p.length;x+=2)if(p[x+1]!=null)m.put((String)p[x],p[x+1]);return m;}}
